#[allow(non_upper_case_globals, non_camel_case_types, non_snake_case, dead_code)]
mod bindings {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

// The implementations live in their own module so that `crate::exports::NAME`
// can only mean an implementation, never a glob-imported bindgen declaration.
mod exports;

// Generated by build.rs: one check per function the headers declare.
#[allow(non_upper_case_globals, unused_imports, dead_code)]
mod abi_checks {
    include!(concat!(env!("OUT_DIR"), "/abi_checks.rs"));
}
